CREATE TEMPORARY VIEW rule_data_${grass_region_without_quote} AS
SELECT
     rule_id
    ,state
    ,exp_test_ids
    ,exp_base_ids
    ,value_type
    ,selection_type
    ,target_type
    ,control_function
    ,is_individual_value
FROM srdi_mart.dim_sr_data_warehouse_tc_rule
where grass_region IN (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
;
--sql_divide_splitter--
-- 获取当前最大可用的分区，并且兼容回溯的场景
set max_regional_date_hour_${grass_region_without_quote} = (
    select
        max(time_str)
    from (
        select
            concat(grass_date,'_',if(hour<10,concat('0',hour),hour)) as  time_str
        from szci_traffic.traffic_active_control_task_item_dump_h
        where grass_region IN (${grass_region}) AND grass_date BETWEEN date_sub(${regional_date}, 1) AND ${regional_date}
        group by grass_date,hour
    ) a
    where time_str<=concat(${regional_date},'_',if(${regional_hour}<10,concat('0',${regional_hour}),${regional_hour}))
);
--sql_divide_splitter--
-- szci_traffic.traffic_active_control_task_item_dump_h only 7 day retentions ，so do not backfill too long ago
INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_tc_item_group_hi
partition(grass_region = ${grass_region}, local_date, local_hour, regional_date, regional_hour)
select
     item_id
    ,a.rule_id
    ,shop_id
    ,if(target_type=5,cast(a.rule_id as string),item_group_id) as item_group_id -- delete deboost old data item_group_id and fillout a default value
    ,target_group
    ,to_json(
        array_distinct(
            transform(scenes,
                x -> CASE 
                    WHEN x = 'search' THEN 'Search'
                    WHEN x = 'dd' THEN 'Daily Discover'
                    WHEN x = 'ymal' THEN 'You May Also Like'
                    WHEN x = 'orderpaid_discover' THEN 'Post Purchase'
                    WHEN x = 'my_purchases_page_ymal' THEN 'Post Purchase'
                    WHEN x = 'shop_page_product_tab_main' THEN 'Shop'
                    WHEN x = 'shop_page_rfy' THEN 'Shop'
                    WHEN x = 'shop_page_main' THEN 'Shop'
                    WHEN x = 'product_detail_page_ftss' THEN 'Shop'
                    ELSE '' END)
        )
    ) as scenes
    ,item_group_start_time
    ,rule_start_time
    ,rule_end_time
    ,mtime
    ,task_status
    ,exp_test_ids
    ,exp_base_ids
    ,value_type
    ,selection_type
    ,target_type
    ,control_function
    ,is_individual_value
    ,if(target_group=3 and b.value_type=2 and b.state=5,0,1) as item_group_if_ongoing
    ,target as item_group_target

    ,date(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"yyyy-MM-dd")) as local_date
    ,cast(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"HH") as int) as local_hour
    ,cast(${regional_date} as date) as regional_date
    ,cast(${regional_hour} as int) as regional_hour
from szci_traffic.traffic_active_control_task_item_dump_h a
left join rule_data_${grass_region_without_quote} b on a.rule_id=b.rule_id
where grass_region IN (${grass_region}) and grass_date = split(${max_regional_date_hour_${grass_region_without_quote}},'_')[0] and hour = cast(split(${max_regional_date_hour_${grass_region_without_quote}},'_')[1] as int)
;
